if ( ! defined( 'ABSPATH' ) ) { exit; } function gc_default_pages_map() { return array( 'home' => array( 'title' => __( 'Home', 'game-changers' ), 'content' => '', 'template' => 'front-page.php', ), 'blog' => array( 'title' => __( 'Blog', 'game-changers' ), 'content' => __( 'The latest stories, updates and press from Game Changers Nigeria.', 'game-changers' ), ), 'enlistments' => array( 'title' => __( 'Join the Academy', 'game-changers' ), 'content' => __( 'Nigeria will not change by noise alone. It will change when informed people organise around purpose, value, and opportunity. Free to join — no payment required.', 'game-changers' ), 'template' => 'page-enlistments.php', ), 'premium-dashboard' => array( 'title' => __( 'Premium Dashboard', 'game-changers' ), 'content' => '', 'template' => 'page-premium-dashboard.php', ), 'premium-login' => array( 'title' => __( 'Premium Login', 'game-changers' ), 'content' => '', 'template' => 'page-premium-login.php', ), 'free-ebook' => array( 'title' => __( 'Free Ebook', 'game-changers' ), 'content' => __( 'Enter the same name and email you registered with (Join the Academy, Premium Membership, or any of our forms) to download the free ebook.', 'game-changers' ), 'template' => 'page-free-ebook.php', ), 'apply-now' => array( 'title' => __( 'Premium Membership', 'game-changers' ), 'content' => __( 'Go further with Premium Membership — priority access to advisory circles, cohort placement, and structured leadership tracks. Enrol and pay securely below.', 'game-changers' ), ), 'become-a-member' => array( 'title' => __( 'Become a Member', 'game-changers' ), 'content' => __( "Join your state chapter and become part of the national movement.", 'game-changers' ), 'template' => 'page-become-a-member.php', ), 'mentor-with-us' => array( 'title' => __( 'Mentor with Us', 'game-changers' ), 'content' => __( "Share your expertise with the next generation of leaders.", 'game-changers' ), 'template' => 'page-mentor-with-us.php', ), 'partner-with-us' => array( 'title' => __( 'Partner With Us', 'game-changers' ), 'content' => __( 'Partner with Game Changers Nigeria as an organisation, donor, or platform. Fill in the form on this page with your proposal and our partnerships team will follow up.', 'game-changers' ), ), 'operational-charter' => array( 'title' => __( 'Operational Charter', 'game-changers' ), 'content' => __( "This page outlines how Game Changers Nigeria operates — our structure, chapters, and code of conduct for members and volunteers. Edit this page any time under Pages in wp-admin.", 'game-changers' ), ), 'terms-privacy' => array( 'title' => __( 'Terms & Privacy', 'game-changers' ), 'content' => __( "This page covers our Terms of Use and Privacy Policy — how we handle the information members and visitors share with us. Edit this page any time under Pages in wp-admin.", 'game-changers' ), ), ); } function gc_seed_default_pages() { foreach ( gc_default_pages_map() as $slug => $data ) { $existing = get_page_by_path( $slug ); if ( $existing ) { continue; } $page_id = wp_insert_post( array( 'post_type' => 'page', 'post_title' => $data['title'], 'post_name' => $slug, 'post_content' => $data['content'], 'post_status' => 'publish', ) ); if ( $page_id && ! is_wp_error( $page_id ) && ! empty( $data['template'] ) ) { update_post_meta( $page_id, '_wp_page_template', $data['template'] ); } } } add_action( 'after_switch_theme', 'gc_seed_default_pages' ); function gc_maybe_reseed_on_update() { $current_version = wp_get_theme( get_template() )->get( 'Version' ); $seen_version = get_option( 'gc_theme_seeded_version' ); if ( $seen_version === $current_version ) { return; } gc_seed_default_pages(); update_option( 'gc_theme_seeded_version', $current_version ); } add_action( 'admin_init', 'gc_maybe_reseed_on_update' ); function gc_configure_reading_settings() { gc_seed_default_pages(); if ( get_option( 'gc_reading_settings_configured' ) ) { return; } $home = get_page_by_path( 'home' ); $blog = get_page_by_path( 'blog' ); if ( $home && $blog ) { update_option( 'show_on_front', 'page' ); update_option( 'page_on_front', $home->ID ); update_option( 'page_for_posts', $blog->ID ); } update_option( 'gc_reading_settings_configured', 1 ); } add_action( 'after_switch_theme', 'gc_configure_reading_settings' ); function gc_page_url( $slug ) { if ( 'chapters-archive' === $slug ) { $link = get_post_type_archive_link( 'gc_chapter' ); return $link ? $link : home_url('/find-a-chapter/'); } if ( 'blog' === $slug ) { $blog_id = (int) get_option( 'page_for_posts' ); if ( $blog_id ) return get_permalink( $blog_id ); } $page = get_page_by_path( trim($slug,'/'), OBJECT, 'page' ); if ( $page ) return get_permalink( $page ); $pages = get_pages(array('post_type'=>'page','post_status'=>'publish','number'=>50,'meta_key'=>'_wp_page_template','meta_compare'=>'EXISTS')); foreach($pages as $candidate){ if(get_post_field('post_name',$candidate->ID)==sanitize_title($slug)) return get_permalink($candidate); } return home_url('/'.trim($slug,'/').'/'); } function gc_seed_platform_pages() { $pages = array( 'academy' => array('title'=>'Leadership Academy','template'=>'page-academy.php'), 'community' => array('title'=>'Community','template'=>''), 'members' => array('title'=>'Members','template'=>'page-members.php','parent'=>'community'), 'alumni' => array('title'=>'Alumni','template'=>'page-alumni.php','parent'=>'community'), 'find-a-chapter' => array('title'=>'Find a Chapter','template'=>'page-find-a-chapter.php','parent'=>'community'), 'mentors' => array('title'=>'Mentors','template'=>'page-mentors.php','parent'=>'community'), 'verify-certificate' => array('title'=>'Verify Certificate','template'=>'page-verify-certificate.php'), 'academy-apply' => array('title'=>'Academy Application','template'=>'page-academy-apply.php'), 'donate' => array('title'=>'Support Game Changers Nigeria','template'=>'page-donate.php'), ); $ids = array(); foreach($pages as $slug=>$data){ $existing = get_page_by_path($slug, OBJECT, 'page'); $parent = !empty($data['parent']) && isset($ids[$data['parent']]) ? $ids[$data['parent']] : 0; if(!$existing){ $existing_id = wp_insert_post(array('post_type'=>'page','post_title'=>$data['title'],'post_name'=>$slug,'post_status'=>'publish','post_parent'=>$parent)); if($existing_id && !is_wp_error($existing_id)) $existing = get_post($existing_id); } if($existing){ $ids[$slug] = $existing->ID; if(!empty($data['template'])) update_post_meta($existing->ID,'_wp_page_template',$data['template']); } } } add_action('after_switch_theme','gc_seed_platform_pages',20); function gc_maybe_seed_platform_pages(){ $v = wp_get_theme(get_template())->get('Version'); if(get_option('gc_platform_pages_seeded_version') === $v) return; gc_seed_platform_pages(); update_option('gc_platform_pages_seeded_version',$v); } add_action('admin_init','gc_maybe_seed_platform_pages'); function gc_seed_complete_public_pages() { $pages = array( 'about' => array('title'=>'About','template'=>'page.php'), 'academy' => array('title'=>'Leadership Academy','template'=>'page-academy.php'), 'community' => array('title'=>'Community','template'=>'page-community.php'), 'members' => array('title'=>'Members','template'=>'page-members.php','parent'=>'community'), 'alumni' => array('title'=>'Alumni','template'=>'page-alumni.php','parent'=>'community'), 'find-a-chapter' => array('title'=>'Find a Chapter','template'=>'page-find-a-chapter.php','parent'=>'community'), 'mentors' => array('title'=>'Mentors','template'=>'page-mentors.php','parent'=>'community'), 'opportunities' => array('title'=>'Opportunities','template'=>'page-opportunities.php'), 'stories' => array('title'=>'Stories','template'=>'page-stories.php'), 'resources' => array('title'=>'Resources','template'=>'page-resources.php'), 'events' => array('title'=>'Events','template'=>'page-events.php'), 'projects' => array('title'=>'Impact Projects','template'=>'page-projects.php'), 'academy-apply' => array('title'=>'Academy Application','template'=>'page-academy-apply.php'), 'donate' => array('title'=>'Support Game Changers Nigeria','template'=>'page-donate.php'), 'verify-certificate' => array('title'=>'Verify Certificate','template'=>'page-verify-certificate.php'), 'mentor-with-us' => array('title'=>'Submit Mentor Application','template'=>'page-mentor-with-us.php'), 'partner-with-us' => array('title'=>'Partner With Us','template'=>'page-partner-with-us.php'), ); $ids = array(); foreach ($pages as $slug=>$data) { $existing = get_page_by_path($slug, OBJECT, 'page'); $parent = !empty($data['parent']) && isset($ids[$data['parent']]) ? $ids[$data['parent']] : 0; if (!$existing) { $id = wp_insert_post(array( 'post_type'=>'page','post_title'=>$data['title'],'post_name'=>$slug, 'post_status'=>'publish','post_parent'=>$parent, 'post_content'=>'', ), true); if (!is_wp_error($id)) $existing=get_post($id); } elseif ($parent && (int)$existing->post_parent !== (int)$parent) { wp_update_post(array('ID'=>$existing->ID,'post_parent'=>$parent)); } if ($existing) { $ids[$slug]=$existing->ID; if (!empty($data['template']) && $data['template'] !== 'page.php') { update_post_meta($existing->ID,'_wp_page_template',$data['template']); } } } } function gc_refresh_routes_on_theme_update() { gc_seed_complete_public_pages(); flush_rewrite_rules(false); update_option('gc_complete_routes_version', wp_get_theme(get_template())->get('Version')); } add_action('after_switch_theme','gc_refresh_routes_on_theme_update',30); function gc_maybe_refresh_routes_on_update() { $v=wp_get_theme(get_template())->get('Version'); if (get_option('gc_complete_routes_version') !== $v) { gc_refresh_routes_on_theme_update(); } } add_action('admin_init','gc_maybe_refresh_routes_on_update',30); add_action('after_switch_theme', function(){ $p=get_page_by_path('about'); if($p){ update_post_meta($p->ID,'_wp_page_template','page-about.php'); } }, 30); function gc_seed_chapter_certificate_pages(){ $pages=array( 'start-a-chapter'=>array('title'=>'Start a Chapter','template'=>'page-start-a-chapter.php'), 'chapter-login'=>array('title'=>'Chapter Leader Login','template'=>'page-chapter-login.php'), 'chapter-dashboard'=>array('title'=>'Chapter Leader Dashboard','template'=>'page-chapter-dashboard.php'), 'certificate'=>array('title'=>'My Certificate','template'=>'page-certificate.php'), ); foreach($pages as $slug=>$d){$p=get_page_by_path($slug);if(!$p){$id=wp_insert_post(array('post_type'=>'page','post_title'=>$d['title'],'post_name'=>$slug,'post_status'=>'publish'));if($id&&!is_wp_error($id))update_post_meta($id,'_wp_page_template',$d['template']);}elseif($p)update_post_meta($p->ID,'_wp_page_template',$d['template']);} } add_action('after_switch_theme','gc_seed_chapter_certificate_pages',30); add_action('admin_init',function(){if(get_option('gc_chapter_certificate_pages_v1')!=='1'){gc_seed_chapter_certificate_pages();update_option('gc_chapter_certificate_pages_v1','1');}});
function gc_seed_national_dashboard_page(){ $p=get_page_by_path('national-dashboard'); if(!$p){$id=wp_insert_post(array('post_type'=>'page','post_title'=>'National Dashboard','post_name'=>'national-dashboard','post_status'=>'publish'));if($id&&!is_wp_error($id))update_post_meta($id,'_wp_page_template','page-national-dashboard.php');}elseif($p)update_post_meta($p->ID,'_wp_page_template','page-national-dashboard.php'); } add_action('after_switch_theme','gc_seed_national_dashboard_page',30); add_action('admin_init',function(){if(get_option('gc_national_dashboard_page_v1')!=='1'){gc_seed_national_dashboard_page();update_option('gc_national_dashboard_page_v1','1');}}); function gc_enforce_page_templates_v22(){ $map=array( 'mentor-with-us'=>'page-mentor-with-us.php', 'become-a-member'=>'page-become-a-member.php', 'start-a-chapter'=>'page-start-a-chapter.php', 'certificate'=>'page-certificate.php', 'academy'=>'page-academy.php', 'find-a-chapter'=>'page-find-a-chapter.php', 'partner-with-us'=>'page-partner-with-us.php', 'game-changer-leadership-program'=>'page-game-changer-leadership-program.php' ); foreach($map as $slug=>$template){$p=get_page_by_path($slug,OBJECT,'page');if($p && get_page_template_slug($p)!==$template)update_post_meta($p->ID,'_wp_page_template',$template);} } add_action('admin_init','gc_enforce_page_templates_v22',30); add_action('after_switch_theme','gc_enforce_page_templates_v22',40);
/* Leadership Program page — ensure template is assigned even if page already exists */
function gc_seed_leadership_program_page() {
	$slug = 'game-changer-leadership-program';
	$p = get_page_by_path( $slug );
	if ( ! $p ) {
		$id = wp_insert_post( array(
			'post_type'    => 'page',
			'post_title'   => 'Leaders Cadres — Leadership Program',
			'post_name'    => $slug,
			'post_status'  => 'publish',
			'post_content' => '',
		) );
		if ( $id && ! is_wp_error( $id ) ) {
			update_post_meta( $id, '_wp_page_template', 'page-game-changer-leadership-program.php' );
		}
	} else {
		update_post_meta( $p->ID, '_wp_page_template', 'page-game-changer-leadership-program.php' );
	}
}
add_action( 'after_switch_theme', 'gc_seed_leadership_program_page', 30 );
add_action( 'admin_init', function () {
	gc_seed_leadership_program_page();
	if ( get_option( 'gc_leadership_program_page_v1' ) !== '1' ) {
		update_option( 'gc_leadership_program_page_v1', '1' );
	}
}, 25 ); 
add_action("admin_init", function(){
  if (get_option("gc_join_free_inner_v1")==="1") return;
  foreach (array("join-free"=>"page-join-free.php","inner-circle"=>"page-inner-circle.php") as $slug=>$tpl){
    $p=get_page_by_path($slug);
    if(!$p){$id=wp_insert_post(array("post_type"=>"page","post_title"=>ucwords(str_replace("-"," ",$slug)),"post_name"=>$slug,"post_status"=>"publish"));
      if($id&&!is_wp_error($id)) update_post_meta($id,"_wp_page_template",$tpl);
    } else { update_post_meta($p->ID,"_wp_page_template",$tpl); }
  }
  update_option("gc_join_free_inner_v1","1");
}, 42);


add_action( 'admin_init', function () {
	if ( get_option( 'gc_payment_help_page_v1' ) === '1' ) {
		return;
	}
	$p = get_page_by_path( 'payment-help' );
	if ( ! $p ) {
		$id = wp_insert_post( array(
			'post_type'   => 'page',
			'post_title'  => 'Payment & Account Help',
			'post_name'   => 'payment-help',
			'post_status' => 'publish',
		) );
		if ( $id && ! is_wp_error( $id ) ) {
			update_post_meta( $id, '_wp_page_template', 'page-payment-help.php' );
		}
	} else {
		update_post_meta( $p->ID, '_wp_page_template', 'page-payment-help.php' );
	}
	update_option( 'gc_payment_help_page_v1', '1' );
}, 40 );
